// Envío promedio histórico: 2.5 días (ver analisis_joyeria.py). Se usa 3 como colchón.
const ENVIO = 3;
const hoy = new Date(); hoy.setHours(0,0,0,0);
const dia = 86400000;
const out = [];
for (const { json: p } of $input.all()) {
  if (p.estado !== 'En producción') continue;
  const ped = new Date(p.fecha_pedido), prom = new Date(p.fecha_prometida);
  const finProd = new Date(ped.getTime() + Number(p.dias_produccion) * dia);
  const llegadaEst = new Date(Math.max(finProd, hoy) + ENVIO * dia);
  const holgura = Math.round((prom - llegadaEst) / dia);
  const especial = p.fecha_especial ? new Date(p.fecha_especial) : null;
  const pierdeFecha = especial && llegadaEst > especial;
  if (holgura < 0 || pierdeFecha) {
    out.push({ json: {
      id_pedido: p.id_pedido, cliente: p.id_cliente, producto: p.producto,
      prometida: p.fecha_prometida, llegada_estimada: llegadaEst.toISOString().slice(0,10),
      dias_retraso: Math.max(0, -holgura), pierde_fecha_especial: !!pierdeFecha,
      prioridad: pierdeFecha ? 'ALTA' : (holgura < -2 ? 'MEDIA' : 'BAJA') } });
  }
}
out.sort((a,b) => (a.json.prioridad > b.json.prioridad ? 1 : -1));
return out.length ? [{ json: { total: out.length, pedidos: out.map(o => o.json) } }] : [];

const { total, pedidos } = $json;
const lineas = pedidos.map(p =>
  `• ${p.prioridad} | ${p.id_pedido} ${p.producto} – llega ${p.llegada_estimada} (+${p.dias_retraso} d)` +
  (p.pierde_fecha_especial ? ' ⚠ después de la fecha especial' : ''));
return [{ json: { texto: `🚨 ${total} pedido(s) en riesgo hoy\n` + lineas.join('\n') +
  `\n\nAcción: priorizar en taller o avisar al cliente antes de que pregunte.` } }];
